def median(xs):
    ys = sorted(xs)
    n = len(ys)
    if not n:
        raise ValueError('Median requires a nonempty list')
    return ys[n // 2] if n % 2 else Q(ys[n // 2 - 1] + ys[n // 2], 2)
results=[]
def check(cid,expr,result):
    results.append({"id":cid,"expression":expr,"passed":bool(result)})
    if not result: print("FAIL",cid,expr)

